import { computed, mount, selector, signal } from 'kerfjs';
import { each } from 'kerfjs/list';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordItem = { id: number; label: string };
let nextPickerId = 0;

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void,
) {
  const counts = { incoming: signal(4), outgoing: signal(7) };
  const active = signal<Source>('incoming');
  const badge = computed(() => `${counts[active.value].value} crates`);
  const records = signal<RecordItem[]>([
    { id: 1, label: 'One' },
    { id: 2, label: 'Two' },
    { id: 3, label: 'Three' },
    { id: 4, label: 'Four' },
  ]);
  const selectedId = signal<number | null>(null);
  const isSelected = selector(selectedId);
  const pickerId = `study-fruit-${++nextPickerId}`;

  const app = document.createElement('div');
  const inspector = document.createElement('div');
  const rows = document.createElement('div');
  app.append(inspector, rows);
  root.append(app);

  const stopInspector = mount(inspector, () => (
    <><output data-badge="" title={badge}>{badge}</output><input data-note="" /></>
  ));

  function row(record: RecordItem) {
    mark('row');
    const selected = isSelected(record.id);
    const ariaSelected = computed(() => selected.value ? 'true' : 'false');
    return (
      <div data-key={record.id} data-row={record.id} aria-selected={ariaSelected}>
        <span>{record.label}</span>
        <input />
      </div>
    );
  }

  const stopRows = mount(rows, () => <>{each(records.value, row)}</>);

  let disposed = false;
  let stopPicker: (() => void) | undefined;

  function replaceRecords(next: RecordItem[]) {
    const editor = document.activeElement;
    if (!(editor instanceof HTMLInputElement) || !rows.contains(editor)) {
      records.value = next;
      return;
    }

    const start = editor.selectionStart;
    const end = editor.selectionEnd;
    const direction = editor.selectionDirection;
    records.value = next;

    const restoreFocus = () => {
      if (disposed || !rows.contains(editor)) return;
      if (document.activeElement !== document.body) return;
      editor.focus({ preventScroll: true });
      if (start !== null && end !== null) {
        editor.setSelectionRange(start, end, direction ?? undefined);
      }
    };
    restoreFocus();
    queueMicrotask(restoreFocus);
  }

  function close() {
    const stop = stopPicker;
    stopPicker = undefined;
    stop?.();
  }

  return {
    count(source: Source, value: number) {
      counts[source].value = value;
    },
    mode(source: Source) {
      active.value = source;
    },
    select(id: number) {
      selectedId.value = id;
    },
    refetch(next: RecordItem[]) {
      replaceRecords(next.slice());
    },
    swap() {
      const next = records.value.slice();
      if (next.length < 2) return;
      [next[0], next[1]] = [next[1], next[0]];
      replaceRecords(next);
    },
    open() {
      if (disposed || stopPicker) return;
      const host = document.createElement('div');
      app.append(host);
      const unmount = mount(host, () => (
        <Combobox
          id={pickerId}
          label="Fruit"
          suggestions={['Apricot', 'Blueberry', 'Cherry']}
          createLabel={false}
        />
      ));
      let live = true;
      const unwire = wireComboboxes(host, {
        onCommit: ({ value }) => {
          if (live) onCommit(value);
        },
      });
      stopPicker = () => {
        live = false;
        unwire();
        unmount();
        host.remove();
      };
    },
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      stopRows();
      stopInspector();
      app.remove();
    },
  };
}
